@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --color-primary: #F02D00;
  --color-primary-hover: #D02700;
  --color-dark: #171717;
  --color-dark-light: #2C2C2C;
  --color-white: #FFFFFF;
  --color-gray-50: #F9FAFB;
  --color-gray-100: #F3F4F6;
  --color-gray-200: #E5E7EB;
  --color-gray-300: #D1D5DB;
  --color-gray-600: #4B5563;
  --color-teal: #0D9488;
  --color-green: #10B981;
  --color-yellow: #F59E0B;

  --font-family: 'Inter', sans-serif;

  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);

  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;

  --transition: all 0.2s ease-in-out;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  color: var(--color-dark);
  background-color: var(--color-white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Banner --- */
.promo-banner {
  background-color: var(--color-dark);
  color: var(--color-white);
  text-align: center;
  padding: 12px 24px;
  font-size: 14px;
  font-weight: 500;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  position: relative;
}
.promo-banner.hidden {
  display: none;
}
.promo-banner .countdown {
  color: var(--color-primary);
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}
.promo-banner .close-btn {
  position: absolute;
  right: 16px;
  color: var(--color-gray-300);
  background: transparent;
  border: none;
  font-size: 20px;
}

/* --- Header --- */
.site-header {
  border-bottom: 1px solid var(--color-gray-200);
  position: sticky;
  top: 0;
  background-color: var(--color-white);
  z-index: 100;
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.logo {
  font-size: 24px;
  font-weight: 800;
  color: var(--color-dark);
  letter-spacing: -0.5px;
}
.logo span {
  color: var(--color-primary);
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 32px;
}
.main-nav a {
  font-weight: 500;
  color: var(--color-gray-600);
}
.main-nav a:hover, .main-nav a.active {
  color: var(--color-primary);
}
.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 15px;
  transition: var(--transition);
}
.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-white);
}
.btn-primary:hover {
  background-color: var(--color-primary-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.btn-outline {
  border: 1px solid var(--color-gray-300);
  color: var(--color-dark);
}
.btn-outline:hover {
  border-color: var(--color-dark);
  background-color: var(--color-gray-50);
}

/* --- Carousels --- */
.carousel-section {
  padding: 64px 0;
  position: relative;
}
.carousel-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 32px;
}
.carousel-header h2 {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.5px;
}
.carousel-controls {
  display: flex;
  gap: 12px;
}
.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--color-gray-200);
  background: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}
.carousel-btn:hover {
  border-color: var(--color-dark);
  background: var(--color-gray-50);
}
.carousel-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none;  /* IE and Edge */
  padding-bottom: 24px; /* for shadows */
}
.carousel-track::-webkit-scrollbar {
  display: none;
}
.carousel-item {
  flex: 0 0 calc(33.333% - 16px);
  scroll-snap-align: start;
}

@media (max-width: 1024px) {
  .carousel-item { flex: 0 0 calc(50% - 12px); }
}
@media (max-width: 640px) {
  .carousel-item { flex: 0 0 85%; }
  .main-nav { display: none; } /* Basic mobile menu hide for now */
}

/* --- Course Cards --- */
.course-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--color-gray-200);
  transition: var(--transition);
  height: 100%;
  display: flex;
  flex-direction: column;
}
.course-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.course-image {
  height: 200px;
  background-color: var(--color-gray-200);
  position: relative;
  overflow: hidden;
}
.course-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.course-badges {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  gap: 8px;
}
.badge {
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
}
.badge-plus {
  background-color: var(--color-yellow);
  color: var(--color-dark);
}
.badge-discount {
  background-color: var(--color-teal);
  color: var(--color-white);
}
.badge-bestseller {
  background-color: var(--color-dark);
  color: var(--color-white);
}
.course-content {
  padding: 20px;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}
.course-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
  line-height: 1.3;
}
.course-instructor {
  font-size: 14px;
  color: var(--color-gray-600);
  margin-bottom: 12px;
}
.course-desc {
  font-size: 14px;
  color: var(--color-gray-600);
  margin-bottom: 16px;
  flex-grow: 1;
}
.course-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  color: var(--color-gray-600);
  margin-bottom: 16px;
}
.course-rating {
  color: var(--color-yellow);
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 4px;
}
.course-footer {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  border-top: 1px solid var(--color-gray-100);
  padding-top: 16px;
}
.course-price-wrap {
  display: flex;
  flex-direction: column;
}
.course-price-old {
  font-size: 13px;
  color: var(--color-gray-600);
  text-decoration: line-through;
}
.course-price-new {
  font-size: 20px;
  font-weight: 800;
  color: var(--color-dark);
}

/* --- Sections --- */
.section {
  padding: 80px 0;
}
.bg-gray {
  background-color: var(--color-gray-50);
}

/* Home Value Props */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  margin-top: 48px;
}
.value-prop-item {
  text-align: left;
}
.value-icon {
  width: 48px;
  height: 48px;
  background-color: var(--color-teal);
  color: white;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.value-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
}
.value-desc {
  color: var(--color-gray-600);
  font-size: 15px;
}

/* --- Courses Page (Sidebar Layout) --- */
.courses-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 40px;
  padding: 40px 0;
}
@media (max-width: 900px) {
  .courses-layout { grid-template-columns: 1fr; }
  .sidebar { display: none; } /* Mobile filter button should be used */
}
.sidebar-section {
  margin-bottom: 32px;
}
.sidebar-title {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 16px;
  text-transform: uppercase;
  color: var(--color-gray-600);
  letter-spacing: 0.5px;
}
.filter-list li {
  margin-bottom: 8px;
}
.filter-btn {
  font-size: 15px;
  color: var(--color-dark);
  transition: var(--transition);
  text-align: left;
  width: 100%;
  padding: 4px 0;
}
.filter-btn:hover, .filter-btn.active {
  color: var(--color-primary);
  font-weight: 600;
}
.courses-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 24px;
}

/* --- Projects Page (Masonry) --- */
.project-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 40px;
  justify-content: center;
}
.filter-pill {
  padding: 8px 16px;
  background: var(--color-gray-100);
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 500;
  transition: var(--transition);
}
.filter-pill:hover, .filter-pill.active {
  background: var(--color-dark);
  color: var(--color-white);
}
.masonry-grid {
  column-count: 3;
  column-gap: 24px;
}
@media (max-width: 1024px) { .masonry-grid { column-count: 2; } }
@media (max-width: 640px) { .masonry-grid { column-count: 1; } }

.project-card {
  break-inside: avoid;
  margin-bottom: 24px;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  transition: var(--transition);
}
.project-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.project-card img {
  width: 100%;
  border-bottom: 1px solid var(--color-gray-100);
}
.project-info {
  padding: 16px;
}
.project-title {
  font-weight: 700;
  font-size: 16px;
  margin-bottom: 4px;
}
.project-author {
  font-size: 14px;
  color: var(--color-gray-600);
  margin-bottom: 12px;
}
.project-stats {
  display: flex;
  gap: 16px;
  font-size: 13px;
  color: var(--color-gray-600);
}
.project-stats span {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* --- Plus Pricing Page --- */
.plus-hero {
  text-align: center;
  padding: 80px 0 40px;
}
.plus-hero h1 {
  font-size: 48px;
  font-weight: 800;
  margin-bottom: 24px;
  letter-spacing: -1px;
}
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}
.toggle-switch {
  position: relative;
  width: 56px;
  height: 32px;
  background-color: var(--color-primary);
  border-radius: 16px;
  cursor: pointer;
}
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 4px;
  left: 4px;
  width: 24px;
  height: 24px;
  background: white;
  border-radius: 50%;
  transition: var(--transition);
}
.pricing-toggle.monthly .toggle-switch::after {
  transform: translateX(24px);
}
.pricing-cards {
  display: flex;
  justify-content: center;
  max-width: 600px;
  margin: 0 auto;
}
.pricing-card {
  width: 100%;
  background: var(--color-white);
  border: 2px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
  transition: var(--transition);
}
.pricing-card.highlight {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-lg);
  position: relative;
}
.save-badge {
  position: absolute;
  top: -16px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: white;
  padding: 4px 16px;
  border-radius: var(--radius-full);
  font-weight: 700;
  font-size: 14px;
}
.price-display {
  font-size: 48px;
  font-weight: 800;
  margin: 16px 0 8px;
}
.price-display span {
  font-size: 16px;
  font-weight: 500;
  color: var(--color-gray-600);
}
.billing-info {
  color: var(--color-gray-600);
  margin-bottom: 32px;
  font-size: 14px;
}
.benefits-list {
  text-align: left;
  margin-bottom: 32px;
}
.benefits-list li {
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.benefits-list li::before {
  content: '✓';
  color: var(--color-teal);
  font-weight: bold;
}

/* FAQ Accordion */
.faq-section {
  max-width: 800px;
  margin: 80px auto;
}
.faq-item {
  border-bottom: 1px solid var(--color-gray-200);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 24px 0;
  font-size: 18px;
  font-weight: 600;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-answer {
  padding-bottom: 24px;
  color: var(--color-gray-600);
  display: none;
  line-height: 1.6;
}
.faq-item.active .faq-answer {
  display: block;
}
.faq-question::after {
  content: '+';
  font-size: 24px;
  transition: var(--transition);
}
.faq-item.active .faq-question::after {
  transform: rotate(45deg);
}

/* --- Login Form --- */
.login-container {
  max-width: 400px;
  margin: 80px auto;
  padding: 40px;
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
}
.login-container h1 {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 8px;
  text-align: center;
}
.login-container p {
  text-align: center;
  color: var(--color-gray-600);
  margin-bottom: 32px;
}
.social-login {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}
.btn-social {
  width: 100%;
  padding: 12px;
  border: 1px solid var(--color-gray-300);
  border-radius: var(--radius-md);
  font-weight: 600;
  background: var(--color-white);
}
.btn-social.facebook { background: #1877F2; color: white; border-color: #1877F2; }
.btn-social.apple { background: #000; color: white; border-color: #000; }
.divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 24px 0;
  color: var(--color-gray-600);
  font-size: 14px;
}
.divider::before, .divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--color-gray-200);
}
.divider:not(:empty)::before { margin-right: 16px; }
.divider:not(:empty)::after { margin-left: 16px; }
.form-group {
  margin-bottom: 20px;
  position: relative;
}
.form-control {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--color-gray-300);
  border-radius: var(--radius-md);
  font-family: inherit;
  font-size: 15px;
}
.form-control:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(240, 45, 0, 0.1);
}
.password-toggle {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-gray-600);
  font-size: 14px;
}
.btn-submit {
  width: 100%;
  padding: 14px;
  border-radius: var(--radius-md);
  font-size: 16px;
  margin-top: 8px;
}
.login-links {
  margin-top: 24px;
  text-align: center;
  font-size: 14px;
}
.login-links a {
  color: var(--color-primary);
  font-weight: 600;
  display: block;
  margin-bottom: 12px;
}

/* --- Footer --- */
.site-footer {
  background-color: var(--color-dark);
  color: var(--color-white);
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  margin-bottom: 64px;
}
.footer-col h3 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 20px;
  color: var(--color-gray-300);
}
.footer-col ul li {
  margin-bottom: 12px;
}
.footer-col a {
  color: var(--color-gray-300);
  font-size: 14px;
}
.footer-col a:hover {
  color: var(--color-white);
}
.footer-bottom {
  border-top: 1px solid var(--color-dark-light);
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 24px;
  font-size: 14px;
  color: var(--color-gray-300);
}
.footer-legal a {
  margin-right: 16px;
}

@media (max-width: 768px) {
  .footer-col h3 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--color-dark-light);
    padding-bottom: 12px;
  }
  .footer-col h3::after {
    content: '+';
  }
  .footer-col ul {
    display: none;
    padding-top: 12px;
  }
  .footer-col.active ul {
    display: block;
  }
  .footer-col.active h3::after {
    content: '-';
  }
}

document.addEventListener('DOMContentLoaded', () => {

  // 1. Promotional Banner Dismissal
  const banner = document.getElementById('promo-banner');
  const dismissBtn = document.getElementById('close-banner');
  if (banner && dismissBtn) {
    dismissBtn.addEventListener('click', () => {
      banner.classList.add('hidden');
    });
  }

  // 2. Carousel Functionality
  const carousels = document.querySelectorAll('.carousel-container');
  carousels.forEach(carousel => {
    const track = carousel.querySelector('.carousel-track');
    const prevBtn = carousel.querySelector('.btn-prev');
    const nextBtn = carousel.querySelector('.btn-next');

    if (track && prevBtn && nextBtn) {
      const scrollAmount = () => track.clientWidth > 768 ? track.clientWidth / 2 : track.clientWidth;

      nextBtn.addEventListener('click', () => {
        track.scrollBy({ left: scrollAmount(), behavior: 'smooth' });
      });

      prevBtn.addEventListener('click', () => {
        track.scrollBy({ left: -scrollAmount(), behavior: 'smooth' });
      });
    }
  });

  // 3. Plus Pricing Toggle
  const pricingToggleWrap = document.getElementById('pricing-toggle-wrap');
  const priceDisplayAmount = document.getElementById('price-amount');
  const billingInfo = document.getElementById('billing-info');
  const creditsInfo = document.getElementById('credits-info');

  if (pricingToggleWrap) {
    pricingToggleWrap.addEventListener('click', () => {
      const isMonthly = pricingToggleWrap.classList.contains('monthly');

      if (isMonthly) {
        // Switch to Yearly
        pricingToggleWrap.classList.remove('monthly');
        priceDisplayAmount.innerHTML = '$14.59<span>/month</span>';
        billingInfo.textContent = 'Billed as $174.50/year. Cancel anytime.';
        creditsInfo.textContent = '12 annual credits';
      } else {
        // Switch to Monthly
        pricingToggleWrap.classList.add('monthly');
        priceDisplayAmount.innerHTML = '$33.90<span>/month</span>';
        billingInfo.textContent = 'Billed as $33.90/month. Cancel anytime.';
        creditsInfo.textContent = '1 credit per month';
      }
    });
  }

  // 4. FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    question.addEventListener('click', () => {
      // Close others (optional)
      faqItems.forEach(i => {
        if (i !== item) i.classList.remove('active');
      });
      // Toggle current
      item.classList.toggle('active');
    });
  });

  // 5. Course Filtering (Sidebar)
  const filterBtns = document.querySelectorAll('.filter-btn');
  const courseCards = document.querySelectorAll('.course-card-wrapper'); // Wrapper needed if grid items

  if (filterBtns.length > 0 && courseCards.length > 0) {
    filterBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        // Remove active class from all
        filterBtns.forEach(b => b.classList.remove('active'));
        // Add active to clicked
        e.target.classList.add('active');

        const filterValue = e.target.getAttribute('data-filter');

        courseCards.forEach(card => {
          if (filterValue === 'all') {
            card.style.display = 'block';
          } else {
            const categories = card.getAttribute('data-category');
            if (categories && categories.includes(filterValue)) {
              card.style.display = 'block';
            } else {
              card.style.display = 'none';
            }
          }
        });
      });
    });
  }

  // 6. Project Filtering (Masonry)
  const projectFilters = document.querySelectorAll('.filter-pill');
  const projectCards = document.querySelectorAll('.project-card');

  if (projectFilters.length > 0 && projectCards.length > 0) {
    projectFilters.forEach(btn => {
      btn.addEventListener('click', (e) => {
        projectFilters.forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');

        const filterValue = e.target.getAttribute('data-filter');

        projectCards.forEach(card => {
          if (filterValue === 'all') {
            card.style.display = 'block';
          } else {
            const fields = card.getAttribute('data-field');
            if (fields && fields.includes(filterValue)) {
              card.style.display = 'block';
            } else {
              card.style.display = 'none';
            }
          }
        });
      });
    });
  }

  // 7. Password Visibility Toggle
  const togglePasswordBtn = document.getElementById('toggle-password');
  const passwordInput = document.getElementById('password');

  if (togglePasswordBtn && passwordInput) {
    togglePasswordBtn.addEventListener('click', () => {
      const type = passwordInput.getAttribute('type') === 'password' ? 'text' : 'password';
      passwordInput.setAttribute('type', type);
      togglePasswordBtn.textContent = type === 'password' ? 'Show' : 'Hide';
    });
  }

  // 8. Footer Mobile Accordion
  const footerCols = document.querySelectorAll('.footer-col h3');
  if (window.innerWidth <= 768) {
    footerCols.forEach(col => {
      col.addEventListener('click', () => {
        col.parentElement.classList.toggle('active');
      });
    });
  }

});
